import type { Metadata } from "next";
import { UnderwritingReviewScreen } from "./screen";

export const metadata: Metadata = {
  title: "引受査定 | 自動車保険（架空データ）",
  description:
    "自動車保険の申し込みを引き受けるかどうかを、担当者が審査する画面。データはすべて架空です。",
};

export default function Page() {
  return <UnderwritingReviewScreen />;
}

"use client";

import * as React from "react";
import {
  IconAlertTriangle,
  IconCircleCheck,
  IconCircleX,
} from "@tabler/icons-react";
import { Badge } from "@gunjo/ui";
import { JUDGEMENT_LABEL } from "./lib";
import type { Judgement } from "./types";

const JUDGEMENT_VARIANT = {
  pass: "success",
  review: "warning",
  fail: "destructive",
} as const;

const JUDGEMENT_ICON = {
  pass: IconCircleCheck,
  review: IconAlertTriangle,
  fail: IconCircleX,
} as const;

/**
 * 合格 / 要確認 / 不合格のピル。
 * 色だけに意味を載せないよう、アイコンと文字を必ず添える。
 */
export function JudgementBadge({
  judgement,
  size = "default",
  count,
}: {
  judgement: Judgement;
  size?: "sm" | "default" | "lg";
  count?: number;
}) {
  const Glyph = JUDGEMENT_ICON[judgement];
  return (
    <Badge variant={JUDGEMENT_VARIANT[judgement]} size={size} icon={<Glyph />}>
      {JUDGEMENT_LABEL[judgement]}
      {typeof count === "number" ? ` ${count}` : ""}
    </Badge>
  );
}

/** 見出しの下に置く、節のかたまり用の小見出し（h4）。 */
export function SubHeading({
  children,
  id,
}: {
  children: React.ReactNode;
  id?: string;
}) {
  return (
    <h4 id={id} className="text-sm font-semibold text-foreground">
      {children}
    </h4>
  );
}

/** ラベルと値を縦に並べる小さな枠。数字を読ませたいところで使う。 */
export function FactBox({
  label,
  value,
  note,
}: {
  label: React.ReactNode;
  value: React.ReactNode;
  note?: React.ReactNode;
}) {
  return (
    <div className="rounded-md border bg-card p-3">
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="mt-1 text-base font-semibold tabular-nums">{value}</div>
      {note ? <div className="mt-1 text-xs text-muted-foreground">{note}</div> : null}
    </div>
  );
}

"use client";

import * as React from "react";
import { IconInfoCircle } from "@tabler/icons-react";
import {
  Alert,
  AlertDescription,
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertTitle,
  AmountBreakdown,
  ApprovalSteps,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Checkbox,
  CheckList,
  Grid,
  HStack,
  List,
  ListItem,
  MetadataList,
  RadioGroup,
  RadioGroupItem,
  RevealSection,
  SegmentedControl,
  Select,
  Separator,
  Statistic,
  Textarea,
  VStack,
} from "@gunjo/ui";
import type { AmountLine, ApprovalStep } from "@gunjo/ui";
import { SubHeading } from "./bits";
import {
  APPROVERS,
  CURRENT_USER,
  DECLINE_REASONS,
  DEDUCTIBLE_OPTIONS,
  SURCHARGE_OPTIONS,
} from "./data";
import {
  approvalChain,
  approvalRoute,
  calculatePremium,
  countJudgements,
  DECISION_LABEL,
  DECLINE_REASON_MIN_LENGTH,
  describeConditions,
  evaluateGate,
  JUDGEMENT_LABEL,
  quotedPremium,
  REASON_MIN_LENGTH,
  STAGE_LABEL,
  yen,
} from "./lib";
import type {
  ApprovalStage,
  DecisionConditions,
  DecisionKind,
  Submission,
  UnderwritingCase,
} from "./types";

const STAGE_PERSON: Record<ApprovalStage, { name: string; role: string }> = {
  reviewer: { name: CURRENT_USER.name, role: CURRENT_USER.role },
  manager: { name: APPROVERS.manager.name, role: APPROVERS.manager.role },
  director: { name: APPROVERS.director.name, role: APPROVERS.director.role },
};

const STEP_STATE_LABELS = {
  pending: "未着手",
  current: "対応中",
  approved: "処理済み",
  rejected: "差し戻し",
  skipped: "省略",
} as const;

const DECISION_OPTIONS: {
  value: DecisionKind;
  label: string;
  description: string;
}[] = [
  {
    value: "accept",
    label: DECISION_LABEL.accept,
    description: "申し込みの内容のまま引き受けます。補償も保険料も変わりません。",
  },
  {
    value: "conditional",
    label: DECISION_LABEL.conditional,
    description:
      "免責金額を上げる・特約を外す・保険料を割り増す、のいずれかを付けて引き受けます。条件は下で選びます。",
  },
  {
    value: "decline",
    label: DECISION_LABEL.decline,
    description:
      "この申し込みは引き受けません。申込者と代理店に通知され、記録が残ります。課長以上の決裁が要ります。",
  },
];

function stageLine(stage: ApprovalStage) {
  const person = STAGE_PERSON[stage];
  return `${person.name}（${person.role}）`;
}

export interface DecisionPanelProps {
  record: UnderwritingCase;
  submission: Submission | null;
  onSubmit: (submission: Submission) => void;
  onWithdraw: () => void;
}

/**
 * 判断・保険料・決裁の3枚。
 *
 * ここが画面の芯なので、次の3つを守っている。
 * - 既定では何も選ばれていない（画面が判断を先取りしない）
 * - どの判断でも理由を書かないと確定できない
 * - 条件を動かすと、その場で保険料が変わる
 */
export function DecisionPanel({
  record,
  submission,
  onSubmit,
  onWithdraw,
}: DecisionPanelProps) {
  const [decision, setDecision] = React.useState<DecisionKind | null>(null);
  const [reason, setReason] = React.useState("");
  const [declineReasonCode, setDeclineReasonCode] = React.useState("");
  const [declineAcknowledged, setDeclineAcknowledged] = React.useState(false);
  const [confirmOpen, setConfirmOpen] = React.useState(false);
  const [conditions, setConditions] = React.useState<DecisionConditions>({
    deductible: record.currentDeductible,
    removedRiderIds: [],
    surchargeRate: 0,
  });

  const blockersRef = React.useRef<HTMLDivElement>(null);

  // 条件付き以外では、条件は付かないものとして保険料を出す。
  const effectiveConditions: DecisionConditions =
    decision === "conditional"
      ? conditions
      : { deductible: record.currentDeductible, removedRiderIds: [], surchargeRate: 0 };

  const quote = React.useMemo(() => quotedPremium(record), [record]);
  const premium = React.useMemo(
    () => calculatePremium(record, effectiveConditions),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [record, effectiveConditions.deductible, effectiveConditions.removedRiderIds, effectiveConditions.surchargeRate],
  );

  const conditionLines = describeConditions(record, effectiveConditions);
  const route = approvalRoute(record, decision);
  const counts = countJudgements(record.criteria);
  const gate = evaluateGate({
    decision,
    reason,
    conditions,
    record,
    declineReasonCode,
    declineAcknowledged,
  });

  const difference = premium.total - quote.total;

  const breakdownLines: AmountLine[] = [
    ...premium.items.map<AmountLine>((item) => ({
      type: "line",
      label: item.label,
      amount: item.amount,
      kind: item.kind,
      note: item.note,
    })),
    { type: "subtotal", label: "小計", amount: premium.subtotal },
  ];
  if (premium.surcharge !== 0) {
    breakdownLines.push({
      type: "line",
      label: `保険料の割増（${effectiveConditions.surchargeRate}%）`,
      amount: premium.surcharge,
      kind: "add",
      note: `小計 ${yen(premium.subtotal)} × ${effectiveConditions.surchargeRate}%`,
    });
  }

  const chain = approvalChain(route.stage);
  const steps: ApprovalStep[] = chain.map((stage) => {
    const person = STAGE_PERSON[stage];
    if (!submission) {
      return {
        label: `${STAGE_LABEL[stage]}${stage === "reviewer" ? "" : "決裁"}`,
        state: stage === "reviewer" ? "current" : "pending",
        actor: `${person.name}（${person.role}）`,
      };
    }
    if (stage === "reviewer") {
      return {
        label: "査定担当",
        state: "approved",
        actor: `${person.name}（${person.role}）`,
        timestamp: submission.decidedAt,
        comment: `${DECISION_LABEL[submission.decision]}：${submission.reason}`,
      };
    }
    const isNext = chain[chain.indexOf(stage) - 1] === "reviewer";
    return {
      label: `${STAGE_LABEL[stage]}決裁`,
      state: isNext ? "current" : "pending",
      actor: `${person.name}（${person.role}）`,
    };
  });

  const currentHolder: ApprovalStage = submission
    ? (chain[1] ?? "reviewer")
    : "reviewer";
  const nextHolder: ApprovalStage | null = submission
    ? (chain[2] ?? null)
    : (chain[1] ?? null);

  function handleAttempt() {
    if (!gate.ready) {
      blockersRef.current?.focus();
      return;
    }
    setConfirmOpen(true);
  }

  function handleConfirm() {
    if (!decision) return;
    const declineLabel =
      decision === "decline"
        ? (DECLINE_REASONS.find((r) => r.value === declineReasonCode)?.label ?? null)
        : null;
    onSubmit({
      caseId: record.id,
      decision,
      reason: reason.trim(),
      conditionLines,
      declineReasonLabel: declineLabel,
      quotedPremium: quote.total,
      finalPremium: premium.total,
      criteriaSnapshot: {
        ...counts,
        flagged: record.criteria
          .filter((c) => c.judgement !== "pass")
          .map((c) => `${c.name}：${JUDGEMENT_LABEL[c.judgement]}（${c.actual}）`),
      },
      stage: route.stage,
      routeReasons: route.reasons,
      decidedBy: `${CURRENT_USER.name}（${CURRENT_USER.role}）`,
      decidedAt: "2026/08/25 11:42",
    });
    setConfirmOpen(false);
  }

  const submitLabel =
    route.stage === "reviewer"
      ? "この内容で確定する"
      : `${STAGE_LABEL[route.stage]}へ回付する`;

  return (
    <VStack gap={5} align="stretch">
      {/* ------------------------------------------------------------ 判断 */}
      <Card>
        <CardHeader>
          <CardTitle as="h3">判断</CardTitle>
          <CardDescription>
            自動判定は材料です。ここで人が決めます。既定では何も選ばれていません。
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-5">
          {submission ? (
            <SubmittedSummary submission={submission} onWithdraw={onWithdraw} />
          ) : (
            <>
              <div className="space-y-3">
                <SubHeading id="decision-heading">下せる判断は3つです</SubHeading>
                <RadioGroup
                  aria-labelledby="decision-heading"
                  value={decision ?? ""}
                  onValueChange={(value) => setDecision(value as DecisionKind)}
                  className="space-y-3"
                >
                  {DECISION_OPTIONS.map((option) => (
                    <RadioGroupItem
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      description={option.description}
                    />
                  ))}
                </RadioGroup>
              </div>

              {/* -------------------------------------------- 条件を付ける */}
              <RevealSection open={decision === "conditional"} label="付ける条件">
                <VStack gap={4} align="stretch" className="rounded-md border p-4">
                  <div>
                    <SubHeading>付ける条件</SubHeading>
                    <p className="mt-1 text-xs text-muted-foreground">
                      選ぶたびに、右の保険料がその場で変わります。付けた条件はそのまま記録に残ります。
                    </p>
                  </div>

                  <Select
                    label="車両保険の免責金額（1回目）"
                    description={`いまの申し込みは ${yen(record.currentDeductible)}。上げると車両保険料が下がります。`}
                    value={String(conditions.deductible)}
                    onChange={(event) =>
                      setConditions((prev) => ({
                        ...prev,
                        deductible: Number(event.target.value),
                      }))
                    }
                  >
                    {DEDUCTIBLE_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </Select>

                  <div className="space-y-2">
                    <SubHeading>付帯する特約</SubHeading>
                    <p className="text-xs text-muted-foreground">
                      チェックを外した特約は、この契約から外れます。
                    </p>
                    <CheckList
                      items={record.riders.map((rider) => ({
                        id: rider.id,
                        label: rider.name,
                        description: rider.note,
                        checked: !conditions.removedRiderIds.includes(rider.id),
                        trailing: (
                          <span className="text-sm tabular-nums">{yen(rider.premium)}</span>
                        ),
                      }))}
                      onCheckedChange={(id, checked) =>
                        setConditions((prev) => ({
                          ...prev,
                          removedRiderIds: checked
                            ? prev.removedRiderIds.filter((r) => r !== id)
                            : [...prev.removedRiderIds, id],
                        }))
                      }
                    />
                  </div>

                  <div className="space-y-2">
                    <SubHeading id="surcharge-heading">保険料の割増</SubHeading>
                    <SegmentedControl
                      aria-labelledby="surcharge-heading"
                      value={String(conditions.surchargeRate)}
                      onValueChange={(value) =>
                        setConditions((prev) => ({ ...prev, surchargeRate: Number(value) }))
                      }
                      options={SURCHARGE_OPTIONS.map((rate) => ({
                        value: String(rate),
                        label: rate === 0 ? "割増なし" : `${rate}%`,
                      }))}
                    />
                  </div>

                  {conditionLines.length > 0 ? (
                    <div className="rounded-md bg-muted/50 p-3">
                      <SubHeading>いま付けている条件</SubHeading>
                      <List
                        variant="unordered"
                        marker="dot"
                        spacing="tight"
                        className="mt-2 text-sm"
                      >
                        {conditionLines.map((line) => (
                          <ListItem key={line}>{line}</ListItem>
                        ))}
                      </List>
                    </div>
                  ) : (
                    <p className="text-sm text-muted-foreground">
                      条件はまだ1つも付いていません。上のいずれかを動かしてください。
                    </p>
                  )}
                </VStack>
              </RevealSection>

              {/* ------------------------------------------ 引き受けない */}
              <RevealSection open={decision === "decline"} label="引き受けないと決める前に">
                <VStack gap={4} align="stretch" className="rounded-md border p-4">
                  <div>
                    <SubHeading>引き受けないと決める前に</SubHeading>
                    <p className="mt-1 text-sm">
                      引受不可は、基準にもとづく通常の判断のひとつです。件数が多いこと自体が問題になるものではありません。
                      そのうえで、相手の生活に関わる判断なので、次の4点を読んでから進めてください。
                    </p>
                  </div>

                  <List variant="unordered" marker="dot" spacing="tight" className="text-sm">
                    <ListItem>この判断は申込者と募集代理店に通知されます。</ListItem>
                    <ListItem>判断と理由は5年間保存され、監査と苦情対応のときに読まれます。</ListItem>
                    <ListItem>確定したあとに撤回するには、課長の決裁が要ります。</ListItem>
                    <ListItem>
                      同じ契約者からの再申込は、6か月間は同じ基準で審査されます。
                    </ListItem>
                  </List>

                  <Select
                    label="謝絶事由の区分（必須）"
                    description="社内コードです。理由の本文と食い違わないものを選んでください。"
                    value={declineReasonCode}
                    onChange={(event) => setDeclineReasonCode(event.target.value)}
                  >
                    {DECLINE_REASONS.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </Select>

                  <Checkbox
                    checked={declineAcknowledged}
                    onCheckedChange={setDeclineAcknowledged}
                    label="上の4点を読みました"
                    description="読んだことの記録が残ります。"
                  />
                </VStack>
              </RevealSection>

              {/* ---------------------------------------------- 理由を残す */}
              <div className="space-y-2">
                <SubHeading id="reason-heading">判断の理由（必須）</SubHeading>
                <p className="text-xs text-muted-foreground">
                  半年後に、この案件を知らない人が読んで筋道をたどれるように書いてください。
                  どの判断でも、理由がないと確定できません。
                </p>
                <List variant="unordered" marker="dot" spacing="tight" className="text-xs text-muted-foreground">
                  <ListItem>どの基準項目を、どう見たか</ListItem>
                  <ListItem>自動判定と違う見方をしたなら、その理由</ListItem>
                  <ListItem>条件を付けたなら、なぜその条件にしたのか</ListItem>
                  <ListItem>代理店や契約者に確認したことがあれば、その内容</ListItem>
                </List>
                <Textarea
                  aria-labelledby="reason-heading"
                  value={reason}
                  onChange={(event) => setReason(event.target.value)}
                  rows={6}
                  maxLength={1000}
                  showCount
                  description={`${decision === "decline" ? DECLINE_REASON_MIN_LENGTH : REASON_MIN_LENGTH}文字以上。監査記録として保存されます。`}
                  placeholder="例：走行距離は基準を3,000km超えているが、業務使用の内容を代理店に確認したところ現場移動のみで運搬はないとの回答だった。等級6・事故2件とあわせ、免責金額を10万円に上げたうえで引き受ける。"
                />
              </div>

              {/* -------------------------------------------- 確定できるか */}
              {/*
                Alert の既定は role="alert"（assertive）。理由を打つたびに割り込まれるので、
                role="status" に差し替えて穏やかに読ませる。
              */}
              <div
                ref={blockersRef}
                tabIndex={-1}
                className="rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                {gate.ready ? (
                  <Alert variant="success" role="status" icon={<IconInfoCircle />}>
                    <AlertTitle>確定に必要なものはそろっています</AlertTitle>
                    <AlertDescription>
                      {route.stage === "reviewer"
                        ? "この判断は担当者だけで確定できます。"
                        : `確定すると ${stageLine(route.stage)} へ回ります。`}
                    </AlertDescription>
                  </Alert>
                ) : (
                  <Alert variant="warning" role="status" icon={<IconInfoCircle />}>
                    <AlertTitle>
                      確定するには、あと{gate.blockers.length}件そろえる必要があります
                    </AlertTitle>
                    <AlertDescription>
                      <List variant="unordered" marker="dot" spacing="tight" className="text-sm">
                        {gate.blockers.map((blocker) => (
                          <ListItem key={blocker}>{blocker}</ListItem>
                        ))}
                      </List>
                    </AlertDescription>
                  </Alert>
                )}
              </div>

              <HStack gap={3} wrap justify="end">
                <Button
                  type="button"
                  variant="primary"
                  aria-disabled={!gate.ready}
                  className={gate.ready ? undefined : "opacity-60"}
                  onClick={handleAttempt}
                >
                  {submitLabel}
                </Button>
              </HStack>
            </>
          )}
        </CardContent>
      </Card>

      {/* -------------------------------------------------------- 保険料 */}
      <Card>
        <CardHeader>
          <CardTitle as="h3">保険料</CardTitle>
          <CardDescription>
            条件を動かすと、この金額がその場で変わります。計算の行はすべて残してあります。
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <Grid cols={{ base: 1, sm: 2 }} gap={3}>
            <Statistic
              label="見積の年間保険料"
              value={yen(quote.total)}
              hint="申し込みの内容そのままの金額"
            />
            <Statistic
              label="この条件での年間保険料"
              value={yen(premium.total)}
              change={
                difference === 0
                  ? "見積と同じ"
                  : `${difference > 0 ? "＋" : "−"}${yen(Math.abs(difference))}`
              }
              trend={difference > 0 ? "up" : difference < 0 ? "down" : "flat"}
              tone="muted"
              hint={
                conditionLines.length > 0
                  ? `${conditionLines.length}件の条件を反映`
                  : "条件は付いていません"
              }
            />
          </Grid>

          <AmountBreakdown
            lines={breakdownLines}
            total={{ label: "年間保険料", amount: premium.total }}
            formula={premium.formula}
          />
        </CardContent>
      </Card>

      {/* ---------------------------------------------------------- 決裁 */}
      <Card>
        <CardHeader>
          <CardTitle as="h3">決裁</CardTitle>
          <CardDescription>
            いま誰の手番か、次に誰へ回るかを示します。段は案件の中身と判断の種類で決まります。
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <Grid cols={{ base: 1, sm: 2 }} gap={3}>
            <div className="rounded-md border p-3">
              <div className="text-xs text-muted-foreground">いまの手番</div>
              <div className="mt-1 text-sm font-semibold">{stageLine(currentHolder)}</div>
            </div>
            <div className="rounded-md border p-3">
              <div className="text-xs text-muted-foreground">次に回る先</div>
              <div className="mt-1 text-sm font-semibold">
                {nextHolder ? stageLine(nextHolder) : "なし（この段で終わります）"}
              </div>
            </div>
          </Grid>

          <ApprovalSteps steps={steps} stateLabels={STEP_STATE_LABELS} />

          <Separator />

          <div className="space-y-2">
            <SubHeading>この段になった理由</SubHeading>
            <List variant="unordered" marker="dot" spacing="tight" className="text-sm">
              {route.reasons.map((reasonText) => (
                <ListItem key={reasonText}>{reasonText}</ListItem>
              ))}
            </List>
            {route.stage === "reviewer" ? (
              <p className="text-xs text-muted-foreground">
                担当者だけで確定できる案件です。上位者へ回す必要はありません。
              </p>
            ) : null}
          </div>
        </CardContent>
      </Card>

      {/* ------------------------------------------------------ 確認画面 */}
      <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {decision ? DECISION_LABEL[decision] : ""}として記録します
            </AlertDialogTitle>
            <AlertDialogDescription>
              {record.id}・{record.applicant.name} さんの申し込みについて、
              {route.stage === "reviewer"
                ? "この内容で確定します。"
                : `${stageLine(route.stage)} へ回付します。`}
              判断と理由は監査記録として保存されます。
            </AlertDialogDescription>
          </AlertDialogHeader>

          <div className="space-y-3 text-sm">
            {decision === "decline" ? (
              <p>
                申込者と {record.agency} に、引受不可として通知されます。撤回には課長の決裁が要ります。
              </p>
            ) : null}
            {conditionLines.length > 0 ? (
              <div>
                {/* ダイアログの見出しは AlertDialogTitle（h2）なので、
                    ここで h4 を足すと段が飛ぶ。見出しにはしない。 */}
                <p className="text-sm font-semibold">付ける条件</p>
                <List variant="unordered" marker="dot" spacing="tight" className="mt-1">
                  {conditionLines.map((line) => (
                    <ListItem key={line}>{line}</ListItem>
                  ))}
                </List>
              </div>
            ) : null}
            {decision !== "decline" ? (
              <p className="tabular-nums">
                年間保険料 {yen(premium.total)}
                {difference !== 0 ? `（見積 ${yen(quote.total)}）` : "（見積と同じ）"}
              </p>
            ) : null}
          </div>

          <AlertDialogFooter>
            <AlertDialogCancel>戻って直す</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirm}>{submitLabel}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </VStack>
  );
}

