import { formatCurrency } from "@gunjo/ui";
import { APPROVAL_RULES, DEDUCTIBLE_OPTIONS, TODAY } from "./data";
import type {
  Accident,
  ApprovalStage,
  Criterion,
  DecisionConditions,
  DecisionKind,
  Judgement,
  UnderwritingCase,
} from "./types";

// ---------------------------------------------------------------------------
// 表示のことば
// ---------------------------------------------------------------------------

export const JUDGEMENT_LABEL: Record<Judgement, string> = {
  pass: "合格",
  review: "要確認",
  fail: "不合格",
};

export const DECISION_LABEL: Record<DecisionKind, string> = {
  accept: "そのまま引き受ける",
  conditional: "条件を付けて引き受ける",
  decline: "引き受けない",
};

export const STAGE_LABEL: Record<ApprovalStage, string> = {
  reviewer: "査定担当",
  manager: "課長",
  director: "部長",
};

export const yen = (value: number) => formatCurrency(value);

// ---------------------------------------------------------------------------
// 日付
// ---------------------------------------------------------------------------

/** 日付文字列の差を日数で返す（to − from）。時刻は見ない。 */
export function daysBetween(fromISO: string, toISO: string): number {
  const from = Date.parse(`${fromISO}T00:00:00Z`);
  const to = Date.parse(`${toISO}T00:00:00Z`);
  return Math.round((to - from) / 86_400_000);
}

/** 受付日から今日までの滞留日数。 */
export function waitingDays(record: UnderwritingCase): number {
  return daysBetween(record.receivedAt, TODAY);
}

/** 査定期限まであと何日か。負なら超過。 */
export function daysToDue(record: UnderwritingCase): number {
  return daysBetween(TODAY, record.dueAt);
}

// ---------------------------------------------------------------------------
// 自動判定の集計
// ---------------------------------------------------------------------------

export interface JudgementCounts {
  pass: number;
  review: number;
  fail: number;
}

export function countJudgements(criteria: Criterion[]): JudgementCounts {
  return criteria.reduce<JudgementCounts>(
    (acc, c) => ({ ...acc, [c.judgement]: acc[c.judgement] + 1 }),
    { pass: 0, review: 0, fail: 0 },
  );
}

/** 引っかかった項目（要確認＋不合格）の数。一覧の優先度の材料になる。 */
export function flaggedCount(criteria: Criterion[]): number {
  const counts = countJudgements(criteria);
  return counts.review + counts.fail;
}

// ---------------------------------------------------------------------------
// 保険料の計算
// ---------------------------------------------------------------------------

export interface PremiumLineItem {
  id: string;
  label: string;
  amount: number;
  kind: "add" | "subtract";
  note?: string;
}

export interface PremiumResult {
  /** 内訳の行。 */
  items: PremiumLineItem[];
  /** 割増を掛ける前の小計。 */
  subtotal: number;
  /** 割増額。 */
  surcharge: number;
  /** 年間保険料。 */
  total: number;
  /** 計算式の文字列（監査で読むときの手がかり）。 */
  formula: string;
}

/** 免責金額に対応する減額率を引く。見つからなければ0。 */
export function deductibleRate(deductible: number): number {
  return DEDUCTIBLE_OPTIONS.find((o) => o.value === deductible)?.rate ?? 0;
}

/** 条件を付けないときの見積保険料の内訳。 */
export function quotedPremium(record: UnderwritingCase): PremiumResult {
  return calculatePremium(record, {
    deductible: record.currentDeductible,
    removedRiderIds: [],
    surchargeRate: 0,
  });
}

/**
 * 条件を反映した保険料を出す。
 * 途中の行をすべて残すので、あとから「なぜこの金額になったか」を追える。
 */
export function calculatePremium(
  record: UnderwritingCase,
  conditions: DecisionConditions,
): PremiumResult {
  const items: PremiumLineItem[] = [
    {
      id: "base",
      label: "基本保険料",
      amount: record.basePremium,
      kind: "add",
      note: `うち車両保険料 ${yen(record.vehiclePremium)}`,
    },
  ];

  for (const rider of record.riders) {
    const removed = conditions.removedRiderIds.includes(rider.id);
    if (removed) continue;
    items.push({
      id: `rider-${rider.id}`,
      label: rider.name,
      amount: rider.premium,
      kind: "add",
    });
  }

  for (const discount of record.discounts) {
    items.push({
      id: `discount-${discount.id}`,
      label: discount.label,
      amount: discount.amount,
      kind: "subtract",
      note: discount.note,
    });
  }

  const baseRate = deductibleRate(record.currentDeductible);
  const nextRate = deductibleRate(conditions.deductible);
  const deltaRate = nextRate - baseRate;
  const deductibleReduction = Math.round(record.vehiclePremium * deltaRate);

  if (deductibleReduction !== 0) {
    items.push({
      id: "deductible",
      label:
        deductibleReduction > 0
          ? "免責金額の引上げによる減額"
          : "免責金額の引下げによる増額",
      amount: Math.abs(deductibleReduction),
      kind: deductibleReduction > 0 ? "subtract" : "add",
      // AmountBreakdown の note は1行で切り詰められる。長い説明は
      // 「いま付けている条件」と監査用の控えのほうに書く。
      note: `車両保険料 ${yen(record.vehiclePremium)} の${(Math.abs(deltaRate) * 100).toFixed(0)}%`,
    });
  }

  const subtotal = items.reduce(
    (sum, item) => (item.kind === "add" ? sum + item.amount : sum - item.amount),
    0,
  );
  const surcharge = Math.round((subtotal * conditions.surchargeRate) / 100);

  return {
    items,
    subtotal,
    surcharge,
    total: subtotal + surcharge,
    formula: `年間保険料 = （基本保険料 ＋ 付帯する特約 − 各割引 − 免責金額の引上げによる減額）× (1 ＋ 割増率${conditions.surchargeRate}%)`,
  };
}

/** 外した特約の一覧。 */
export function removedRiders(record: UnderwritingCase, conditions: DecisionConditions) {
  return record.riders.filter((r) => conditions.removedRiderIds.includes(r.id));
}

/** 条件を1行ずつ日本語にする。記録にそのまま残す文言でもある。 */
export function describeConditions(
  record: UnderwritingCase,
  conditions: DecisionConditions,
): string[] {
  const lines: string[] = [];
  if (conditions.deductible !== record.currentDeductible) {
    lines.push(
      `車両保険の免責金額を ${yen(record.currentDeductible)} から ${yen(conditions.deductible)} へ変更する`,
    );
  }
  for (const rider of removedRiders(record, conditions)) {
    lines.push(`${rider.name} を外す（${yen(rider.premium)}）`);
  }
  if (conditions.surchargeRate > 0) {
    lines.push(`保険料を ${conditions.surchargeRate}% 割り増す`);
  }
  return lines;
}

// ---------------------------------------------------------------------------
// 決裁の経路
// ---------------------------------------------------------------------------

export interface ApprovalRoute {
  /** 最終的に決裁が要る段。reviewer なら担当者だけで確定できる。 */
  stage: ApprovalStage;
  /** その段になった理由。基準の値とこの案件の値を並べて書く。 */
  reasons: string[];
  /** いま手番の人。 */
  currentHolder: ApprovalStage;
  /** 次に回る先。null なら次はない（確定で終わり）。 */
  nextHolder: ApprovalStage | null;
}

/**
 * 決裁の経路を決める。判断の種類でも変わる（引受不可は必ず課長以上）。
 * decision が未選択のときは、案件そのものの条件だけで判定する。
 */
export function approvalRoute(
  record: UnderwritingCase,
  decision: DecisionKind | null,
): ApprovalRoute {
  const counts = countJudgements(record.criteria);
  const amount = record.vehicle.vehicleInsuredAmount;
  const reasons: string[] = [];
  let stage: ApprovalStage = "reviewer";

  const raise = (next: ApprovalStage) => {
    const order: ApprovalStage[] = ["reviewer", "manager", "director"];
    if (order.indexOf(next) > order.indexOf(stage)) stage = next;
  };

  if (amount > APPROVAL_RULES.directorAmount) {
    raise("director");
    reasons.push(
      `車両保険金額 ${yen(amount)} が部長決裁の基準 ${yen(APPROVAL_RULES.directorAmount)} を超えている`,
    );
  } else if (amount > APPROVAL_RULES.managerAmount) {
    raise("manager");
    reasons.push(
      `車両保険金額 ${yen(amount)} が課長決裁の基準 ${yen(APPROVAL_RULES.managerAmount)} を超えている`,
    );
  }

  if (counts.fail >= APPROVAL_RULES.directorFailCount) {
    raise("director");
    reasons.push(
      `不合格の項目が ${counts.fail} 件で、部長決裁の基準 ${APPROVAL_RULES.directorFailCount} 件以上に当たる`,
    );
  } else if (counts.fail >= APPROVAL_RULES.managerFailCount) {
    raise("manager");
    reasons.push(
      `不合格の項目が ${counts.fail} 件で、課長決裁の基準 ${APPROVAL_RULES.managerFailCount} 件以上に当たる`,
    );
  }

  if (decision === "decline") {
    raise("manager");
    reasons.push("引受不可の判断は、担当者だけでは確定できない（課長以上の決裁が要る）");
  }

  if (reasons.length === 0) {
    reasons.push(
      `車両保険金額 ${yen(amount)} は課長決裁の基準 ${yen(APPROVAL_RULES.managerAmount)} 以下で、不合格の項目もない`,
    );
  }

  const order: ApprovalStage[] = ["reviewer", "manager", "director"];
  const stageIndex = order.indexOf(stage);
  return {
    stage,
    reasons,
    currentHolder: "reviewer",
    nextHolder: stageIndex > 0 ? order[1] : null,
  };
}

/** 決裁の段を、上から順の配列で返す（表示用）。 */
export function approvalChain(stage: ApprovalStage): ApprovalStage[] {
  if (stage === "director") return ["reviewer", "manager", "director"];
  if (stage === "manager") return ["reviewer", "manager"];
  return ["reviewer"];
}

// ---------------------------------------------------------------------------
// 事故歴の傾向
// ---------------------------------------------------------------------------

export interface AccidentTrend {
  count: number;
  totalPaid: number;
  maxPaid: number;
  /** 直近12か月の件数。 */
  recentCount: number;
  /** 事故の種類ごとの件数。 */
  byCategory: { label: string; value: number }[];
  /** 契約者側の過失割合の平均（％）。事故がなければ null。 */
  averageFault: number | null;
  /** 直近2件の間隔（か月）。2件未満なら null。 */
  monthsBetweenLatestTwo: number | null;
  /** 支払保険金が回を追って増えているか。3件以上でのみ判定。 */
  paidTrend: "increasing" | "decreasing" | "mixed" | null;
  /** 数え上げた事実の箇条書き。判断や見込みは書かない。 */
  observations: string[];
}

function monthsBetween(fromISO: string, toISO: string): number {
  const from = new Date(`${fromISO}T00:00:00Z`);
  const to = new Date(`${toISO}T00:00:00Z`);
  return (
    (to.getUTCFullYear() - from.getUTCFullYear()) * 12 +
    (to.getUTCMonth() - from.getUTCMonth())
  );
}

export function accidentTrend(accidents: Accident[]): AccidentTrend {
  const sorted = [...accidents].sort((a, b) => (a.date < b.date ? 1 : -1));
  const count = sorted.length;
  const totalPaid = sorted.reduce((s, a) => s + a.paid, 0);
  const maxPaid = sorted.reduce((s, a) => Math.max(s, a.paid), 0);
  const recentCount = sorted.filter((a) => monthsBetween(a.date, TODAY) < 12).length;

  const categoryMap = new Map<string, number>();
  for (const a of sorted) categoryMap.set(a.category, (categoryMap.get(a.category) ?? 0) + 1);
  const byCategory = [...categoryMap.entries()].map(([label, value]) => ({ label, value }));

  const averageFault =
    count === 0 ? null : Math.round(sorted.reduce((s, a) => s + a.faultRatio, 0) / count);

  const monthsBetweenLatestTwo =
    count >= 2 ? monthsBetween(sorted[1].date, sorted[0].date) : null;

  let paidTrend: AccidentTrend["paidTrend"] = null;
  if (count >= 3) {
    const oldestFirst = [...sorted].reverse();
    const up = oldestFirst.every((a, i) => i === 0 || a.paid > oldestFirst[i - 1].paid);
    const down = oldestFirst.every((a, i) => i === 0 || a.paid < oldestFirst[i - 1].paid);
    paidTrend = up ? "increasing" : down ? "decreasing" : "mixed";
  }

  const observations: string[] = [];
  if (count === 0) {
    observations.push("過去5年に有責事故の記録はない。");
  } else {
    observations.push(
      `5年で${count}件、支払保険金の合計は${yen(totalPaid)}（最大 ${yen(maxPaid)}）。`,
    );
    if (recentCount > 0) {
      observations.push(`うち直近12か月に${recentCount}件。`);
    } else {
      observations.push("直近12か月には記録がない。");
    }
    if (byCategory.length === 1) {
      observations.push(`${count}件とも種類は「${byCategory[0].label}」でそろっている。`);
    } else {
      observations.push(
        `種類の内訳は ${byCategory.map((c) => `${c.label}${c.value}件`).join("・")}。`,
      );
    }
    if (monthsBetweenLatestTwo !== null) {
      observations.push(`直近2件の間隔は${monthsBetweenLatestTwo}か月。`);
    }
    if (averageFault !== null) {
      observations.push(`契約者側の過失割合は平均${averageFault}%。`);
    }
    if (paidTrend === "increasing") {
      observations.push("支払保険金は古い順に見ると毎回増えている。");
    } else if (paidTrend === "decreasing") {
      observations.push("支払保険金は古い順に見ると毎回減っている。");
    } else if (paidTrend === "mixed") {
      observations.push("支払保険金の増減に一方向の並びはない。");
    }
  }

  return {
    count,
    totalPaid,
    maxPaid,
    recentCount,
    byCategory,
    averageFault,
    monthsBetweenLatestTwo,
    paidTrend,
    observations,
  };
}

// ---------------------------------------------------------------------------
// 確定できるかどうか
// ---------------------------------------------------------------------------

/** 理由として求める最低の文字数。監査で読めるだけの分量を担保する。 */
export const REASON_MIN_LENGTH = 40;
export const DECLINE_REASON_MIN_LENGTH = 60;

export interface GateState {
  /** 満たしていない条件。1つでもあれば確定できない。 */
  blockers: string[];
  ready: boolean;
}

export function evaluateGate(input: {
  decision: DecisionKind | null;
  reason: string;
  conditions: DecisionConditions;
  record: UnderwritingCase;
  declineReasonCode: string;
  declineAcknowledged: boolean;
}): GateState {
  const { decision, reason, conditions, record, declineReasonCode, declineAcknowledged } = input;
  const blockers: string[] = [];

  if (!decision) {
    blockers.push("判断（引き受ける / 条件を付ける / 引き受けない）を選ぶ");
  }

  const minLength = decision === "decline" ? DECLINE_REASON_MIN_LENGTH : REASON_MIN_LENGTH;
  // 文言は一文字ごとに変えない。読み上げの領域に置くので、
  // 打つたびに読み直されると使いものにならなくなる。残り字数は文字数計に任せる。
  if (reason.trim().length < minLength) {
    blockers.push(`判断の理由を${minLength}文字以上書く（監査で読むため）`);
  }

  if (decision === "conditional" && describeConditions(record, conditions).length === 0) {
    blockers.push("付ける条件を1つ以上選ぶ");
  }

  if (decision === "decline") {
    if (!declineReasonCode) blockers.push("謝絶事由の区分を選ぶ");
    if (!declineAcknowledged) blockers.push("引受不可にしたあと何が起きるかを読んで、確認にチェックを入れる");
  }

  return { blockers, ready: blockers.length === 0 };
}

"use client";

import * as React from "react";
import type { ColumnDef } from "@gunjo/ui";
import { Badge, DataTable, ExpiryBadge, HStack, VStack } from "@gunjo/ui";
import { TODAY } from "./data";
import { countJudgements, waitingDays, yen } from "./lib";
import { JudgementBadge } from "./bits";
import type { UnderwritingCase } from "./types";

/** 査定期限のチップ。ExpiryBadge の既定の語（有効・失効）は査定期限に合わないので言い換える。 */
const DUE_LABELS = {
  valid: "期限内",
  expiring: "期限が近い",
  expired: "期限超過",
  missing: "期限未設定",
} as const;

function formatDate(value: string) {
  return value.replaceAll("-", "/");
}

/** 引っかかった項目のピル。0件のときは「すべて合格」と言い切る。 */
function FlagCell({ record }: { record: UnderwritingCase }) {
  const counts = countJudgements(record.criteria);
  if (counts.fail === 0 && counts.review === 0) {
    return <JudgementBadge judgement="pass" size="sm" />;
  }
  return (
    <HStack gap={1} wrap>
      {counts.fail > 0 ? (
        <JudgementBadge judgement="fail" size="sm" count={counts.fail} />
      ) : null}
      {counts.review > 0 ? (
        <JudgementBadge judgement="review" size="sm" count={counts.review} />
      ) : null}
    </HStack>
  );
}

export interface QueueTableProps {
  cases: UnderwritingCase[];
  selectedId: string | null;
  onSelect: (record: UnderwritingCase) => void;
  /** 表の accessible name を、画面上の見出しに結びつけるための id。 */
  labelledBy: string;
}

export function QueueTable({ cases, selectedId, onSelect, labelledBy }: QueueTableProps) {
  const columns = React.useMemo<ColumnDef<UnderwritingCase, unknown>[]>(
    () => [
      {
        id: "due",
        accessorFn: (row) => row.dueAt,
        header: "査定期限",
        size: 190,
        cell: ({ row }) => (
          <ExpiryBadge
            value={row.original.dueAt}
            today={TODAY}
            warnWithinDays={4}
            labels={DUE_LABELS}
            formatDate={(d) =>
              `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
            }
            className="flex-wrap"
          />
        ),
      },
      {
        id: "case",
        accessorFn: (row) => `${row.applicant.name} ${row.applicant.kana} ${row.id} ${row.agency}`,
        header: "契約者・受付番号",
        enableSorting: false,
        size: 240,
        cell: ({ row }) => (
          <VStack gap={1} align="start">
            <HStack gap={2} align="center" wrap>
              <span className="font-medium">{row.original.applicant.name}</span>
              <span className="text-xs text-muted-foreground">
                {row.original.applicant.age}歳
              </span>
              {row.original.id === selectedId ? (
                <Badge variant="outline" size="sm">
                  選択中
                </Badge>
              ) : null}
            </HStack>
            <span className="text-xs tabular-nums text-muted-foreground">
              {row.original.id}・{row.original.agency}
            </span>
          </VStack>
        ),
      },
      {
        id: "amount",
        accessorFn: (row) => row.vehicle.vehicleInsuredAmount,
        header: "車両保険金額",
        size: 150,
        cell: ({ row }) => (
          <VStack gap={1} align="start">
            <span className="font-medium tabular-nums">
              {yen(row.original.vehicle.vehicleInsuredAmount)}
            </span>
            <span className="text-xs text-muted-foreground">
              {row.original.vehicle.maker.replace("（架空）", "")} {row.original.vehicle.model}
            </span>
          </VStack>
        ),
      },
      {
        id: "flags",
        accessorFn: (row) => {
          const counts = countJudgements(row.criteria);
          // 不合格を重く数えて並べ替えの基準にする。
          return counts.fail * 10 + counts.review;
        },
        header: "自動判定で引っかかった項目",
        size: 200,
        cell: ({ row }) => <FlagCell record={row.original} />,
      },
      {
        id: "waiting",
        accessorFn: (row) => waitingDays(row),
        header: "待っている日数",
        size: 150,
        cell: ({ row }) => (
          <VStack gap={1} align="start">
            <span className="tabular-nums">{waitingDays(row.original)}日</span>
            <span className="text-xs text-muted-foreground">
              受付 {formatDate(row.original.receivedAt)}
            </span>
          </VStack>
        ),
      },
      {
        id: "assignee",
        accessorFn: (row) => row.assignee,
        header: "担当者",
        size: 130,
        cell: ({ row }) => <span className="text-sm">{row.original.assignee}</span>,
      },
    ],
    [selectedId],
  );

  return (
    <DataTable
      columns={columns}
      data={cases}
      pageSize={10}
      onRowClick={onSelect}
      getRowState={(row) => (row.id === selectedId ? "selected" : undefined)}
      filter={{ columnId: "case", placeholder: "契約者名・受付番号で絞り込む" }}
      aria-labelledby={labelledBy}
      caption="査定期限が近い順に並べています。列の見出しを押すと、金額や引っかかった項目の数で並べ替えられます。行を押すと下の「案件の審査」に開きます。"
      labels={{
        noResults: "条件に合う案件はありません。",
        filterPlaceholder: "契約者名・受付番号で絞り込む",
        rowsPerPage: "表示件数",
      }}
      renderCard={(row) => (
        <VStack gap={2} align="stretch">
          <HStack gap={2} justify="between" align="start" wrap>
            <VStack gap={1} align="start">
              <HStack gap={2} align="center" wrap>
                <span className="font-medium">{row.applicant.name}</span>
                <span className="text-xs text-muted-foreground">{row.applicant.age}歳</span>
                {row.id === selectedId ? (
                  <Badge variant="outline" size="sm">
                    選択中
                  </Badge>
                ) : null}
              </HStack>
              <span className="text-xs tabular-nums text-muted-foreground">{row.id}</span>
            </VStack>
            <span className="shrink-0 text-sm font-medium tabular-nums">
              {yen(row.vehicle.vehicleInsuredAmount)}
            </span>
          </HStack>

          <ExpiryBadge
            value={row.dueAt}
            today={TODAY}
            warnWithinDays={4}
            labels={DUE_LABELS}
            className="flex-wrap"
          />

          <FlagCell record={row} />

          <p className="text-xs text-muted-foreground">
            受付 {formatDate(row.receivedAt)}・{waitingDays(row)}日待ち・担当 {row.assignee}
          </p>
        </VStack>
      )}
    />
  );
}

"use client";

import * as React from "react";
import { IconInboxOff } from "@tabler/icons-react";
import {
  Badge,
  Container,
  DesktopPageHeader,
  EmptyState,
  Grid,
  HStack,
  SegmentedControl,
  StatGroup,
  VStack,
} from "@gunjo/ui";
import { CASES, CURRENT_USER, INSURER } from "./data";
import { countJudgements, daysToDue, waitingDays } from "./lib";
import { AccidentPanel } from "./accident-panel";
import { ApplicationPanel } from "./application-panel";
import { CriteriaPanel } from "./criteria-panel";
import { DecisionPanel } from "./decision-panel";
import { QueueSkeleton, ReviewSkeleton } from "./skeletons";
import { QueueTable } from "./queue-table";
import { TimelinePanel } from "./timeline-panel";
import type { Submission, UnderwritingCase } from "./types";

type FilterKey = "open" | "due-soon" | "awaiting" | "closed";

// SegmentedControl のラベルは truncate されるので、375px でも切れない長さにする。
const FILTERS: { value: FilterKey; label: string }[] = [
  { value: "open", label: "未処理" },
  { value: "due-soon", label: "期限間近" },
  { value: "awaiting", label: "決裁待ち" },
  { value: "closed", label: "確定済み" },
];

const EMPTY_COPY: Record<FilterKey, { title: string; description: string }> = {
  open: {
    title: "査定待ちの案件はありません",
    description: "受け付けた申し込みはすべて処理済みです。新しい申し込みが届くとここに並びます。",
  },
  "due-soon": {
    title: "期限が4日以内の案件はありません",
    description: "急ぎのものはいまのところありません。「未処理」に切り替えると、残りの案件が見られます。",
  },
  awaiting: {
    title: "決裁待ちの案件はありません",
    description:
      "上位者へ回付した案件がここに並びます。いまは、あなたが回付したものはありません。",
  },
  closed: {
    title: "確定済みの案件はありません",
    description: "担当者だけで確定した案件がここに並びます。",
  },
};

export function UnderwritingReviewScreen() {
  const [filter, setFilter] = React.useState<FilterKey>("open");
  const [loading, setLoading] = React.useState(true);
  const [selectedId, setSelectedId] = React.useState<string | null>(CASES[0].id);
  const [submissions, setSubmissions] = React.useState<Record<string, Submission>>({});

  const reviewHeadingRef = React.useRef<HTMLHeadingElement>(null);

  // 絞り込みを変えるたびに読み込み直す。最初の表示も同じ道を通る。
  React.useEffect(() => {
    setLoading(true);
    const timer = window.setTimeout(() => setLoading(false), 600);
    return () => window.clearTimeout(timer);
  }, [filter]);

  const visibleCases = React.useMemo(() => {
    return CASES.filter((record) => {
      const submission = submissions[record.id];
      switch (filter) {
        case "open":
          return !submission;
        case "due-soon":
          return !submission && daysToDue(record) <= 4;
        case "awaiting":
          return Boolean(submission) && submission.stage !== "reviewer";
        case "closed":
          return Boolean(submission) && submission.stage === "reviewer";
      }
    });
  }, [filter, submissions]);

  const selected = React.useMemo(
    () => CASES.find((record) => record.id === selectedId) ?? null,
    [selectedId],
  );

  const openCases = CASES.filter((record) => !submissions[record.id]);
  const stats = React.useMemo(
    () => [
      { label: "査定待ち", value: `${openCases.length}件`, hint: "自分の課に割り当てられたもの" },
      {
        label: "期限まで4日以内",
        value: `${openCases.filter((c) => daysToDue(c) <= 4).length}件`,
        hint: "本日は2026年8月25日",
      },
      {
        label: "不合格の項目がある案件",
        value: `${openCases.filter((c) => countJudgements(c.criteria).fail > 0).length}件`,
        hint: "上位者の決裁が要る",
      },
      {
        label: "いちばん長い滞留",
        value: `${openCases.reduce((max, c) => Math.max(max, waitingDays(c)), 0)}日`,
        hint: "受付日からの日数",
      },
    ],
    [openCases],
  );

  function handleSelect(record: UnderwritingCase) {
    setSelectedId(record.id);
    // 一覧から開いたら、審査の見出しへ移る。読み上げでも位置が変わったとわかる。
    window.requestAnimationFrame(() => reviewHeadingRef.current?.focus());
  }

  const submission = selected ? (submissions[selected.id] ?? null) : null;

  return (
    <Container size="2xl" as="main" className="min-h-full space-y-8 bg-background pb-16 pt-6">
      <DesktopPageHeader
        title="引受査定"
        eyebrow={
          <HStack gap={2} align="center" wrap>
            <span>{INSURER}／自動車保険</span>
            <Badge variant="outline" size="sm">
              架空データ
            </Badge>
          </HStack>
        }
        subtitle="申し込みを引き受けるかどうかを決めます。自動判定は材料で、決めるのは担当者です。"
        actions={
          <div className="text-right text-sm">
            <div className="font-medium">{CURRENT_USER.name}</div>
            <div className="text-xs text-muted-foreground">{CURRENT_USER.role}</div>
          </div>
        }
      />

      {/* ------------------------------------------------ 査定待ちの一覧 */}
      <section aria-labelledby="queue-heading" className="space-y-4">
        <h2 id="queue-heading" className="text-lg font-semibold">
          査定待ちの一覧
        </h2>

        <StatGroup items={stats} cols={{ base: 2, lg: 4 }} />

        <div className="space-y-1">
          <SegmentedControl
            aria-label="一覧の絞り込み"
            options={FILTERS}
            value={filter}
            onValueChange={(value) => setFilter(value as FilterKey)}
          />
          <p className="text-xs text-muted-foreground">
            「期限間近」は査定期限まで4日以内のものです。「決裁待ち」は上位者へ回付したもの、
            「確定済み」は担当者だけで確定したものです。
          </p>
        </div>

        {loading ? (
          <QueueSkeleton />
        ) : visibleCases.length === 0 ? (
          <EmptyState
            headingLevel={3}
            icon={<IconInboxOff aria-hidden />}
            title={EMPTY_COPY[filter].title}
            description={EMPTY_COPY[filter].description}
          />
        ) : (
          <QueueTable
            cases={visibleCases}
            selectedId={selectedId}
            onSelect={handleSelect}
            labelledBy="queue-heading"
          />
        )}
      </section>

      {/* ---------------------------------------------------- 案件の審査 */}
      <section aria-labelledby="review-heading" className="space-y-4">
        <h2
          id="review-heading"
          ref={reviewHeadingRef}
          tabIndex={-1}
          className="text-lg font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        >
          {selected
            ? `案件の審査：${selected.id}　${selected.applicant.name} さん`
            : "案件の審査"}
        </h2>

        {loading ? (
          <ReviewSkeleton />
        ) : !selected ? (
          <EmptyState
            headingLevel={3}
            title="案件が選ばれていません"
            description="上の一覧から1件選ぶと、ここに申し込みの内容と判定が出ます。"
          />
        ) : (
          <VStack gap={5} align="stretch">
            <Grid cols={{ base: 1, xl: 2 }} gap={5}>
              <VStack gap={5} align="stretch">
                <ApplicationPanel record={selected} />
                <AccidentPanel record={selected} />
                <CriteriaPanel record={selected} />
              </VStack>

              <VStack gap={5} align="stretch">
                <DecisionPanel
                  key={selected.id}
                  record={selected}
                  submission={submission}
                  onSubmit={(next) =>
                    setSubmissions((prev) => ({ ...prev, [next.caseId]: next }))
                  }
                  onWithdraw={() =>
                    setSubmissions((prev) => {
                      const next = { ...prev };
                      delete next[selected.id];
                      return next;
                    })
                  }
                />
              </VStack>
            </Grid>

            <TimelinePanel record={selected} submission={submission} />
          </VStack>
        )}
      </section>

      <footer className="border-t pt-4 text-xs text-muted-foreground">
        <p>
          この画面のデータはすべて架空です。保険会社名・代理店名・契約者名・車種名・地名は実在しません。
          引受基準の数値も、この画面のために作ったものです。
        </p>
      </footer>
    </Container>
  );
}

