"use client";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Timeline,
} from "@gunjo/ui";
import type { TimelineDataItem } from "@gunjo/ui";
import { DECISION_LABEL, STAGE_LABEL } from "./lib";
import type { Submission, UnderwritingCase } from "./types";

/** この案件について、誰がいつ何をしたか。新しいものが上。 */
export function TimelinePanel({
  record,
  submission,
}: {
  record: UnderwritingCase;
  submission: Submission | null;
}) {
  const entries: TimelineDataItem[] = [];

  if (submission) {
    entries.push({
      time: submission.decidedAt,
      title: `${submission.decidedBy} が「${DECISION_LABEL[submission.decision]}」と判断した`,
      description:
        submission.stage === "reviewer"
          ? `理由：${submission.reason}`
          : `${STAGE_LABEL[submission.stage]}へ回付。理由：${submission.reason}`,
      variant: "active",
    });
  }

  for (const entry of [...record.activity].reverse()) {
    entries.push({
      time: entry.at,
      title: `${entry.actor}：${entry.title}`,
      description: entry.detail,
      variant: entry.tone,
    });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h3">やりとりの記録</CardTitle>
        <CardDescription>
          この案件について、誰がいつ何をしたかの時系列です。新しいものが上にあります。
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Timeline items={entries} />
      </CardContent>
    </Card>
  );
}

/**
 * 引受査定画面のデータ型。
 *
 * 画面に出る値はすべて架空です（会社名・代理店名・人名・車種名・地名を含む）。
 */

/** 社内引受基準に当てはめた結果。合格 / 要確認 / 不合格の3段階。 */
export type Judgement = "pass" | "review" | "fail";

/** 基準1項目ぶんの当てはめ結果。基準の値とこの案件の値を必ず並べて持つ。 */
export interface Criterion {
  id: string;
  /** 基準項目名（年齢・等級・事故歴 …）。 */
  name: string;
  /** 社内基準の値。「7等級以上」「15,000km以下」など、しきい値そのものを書く。 */
  standard: string;
  /** この案件の値。基準と同じ単位・同じ言い方でそろえる。 */
  actual: string;
  judgement: Judgement;
  /** なぜその判定になったか。基準のどこに当たったかを一文で書く。 */
  basis: string;
}

/** 過去5年の事故1件。 */
export interface Accident {
  id: string;
  /** 発生日（YYYY-MM-DD）。 */
  date: string;
  /** 事故の種類（対物 / 人身 / 車両単独 …）。傾向を数えるときの区分でもある。 */
  category: string;
  /** 状況の説明。 */
  situation: string;
  /** 契約者側の過失割合（％）。 */
  faultRatio: number;
  /** 支払保険金（円）。 */
  paid: number;
}

/** 希望する補償1行。 */
export interface Coverage {
  id: string;
  name: string;
  /** 「無制限」があるので文字列で持つ。 */
  amount: string;
  deductible: string;
}

/** 特約1つ。条件付き引受で外す対象になる。 */
export interface Rider {
  id: string;
  name: string;
  /** この特約ぶんの年間保険料（円）。 */
  premium: number;
  note: string;
}

/** 割引1行（保険料から引く額）。 */
export interface Discount {
  id: string;
  label: string;
  amount: number;
  note: string;
}

/** やりとりの記録1件。 */
export interface ActivityEntry {
  id: string;
  /** 表示用の日時（YYYY/MM/DD HH:mm）。 */
  at: string;
  actor: string;
  title: string;
  detail?: string;
  tone: "default" | "muted" | "info" | "success" | "warning" | "destructive";
}

/** 決裁の段。 */
export type ApprovalStage = "reviewer" | "manager" | "director";

export interface UnderwritingCase {
  /** 受付番号。 */
  id: string;
  /** 受付日（YYYY-MM-DD）。 */
  receivedAt: string;
  /** 査定期限（YYYY-MM-DD）。 */
  dueAt: string;
  /** 査定担当者。 */
  assignee: string;
  /** 募集代理店（架空）。 */
  agency: string;

  applicant: {
    name: string;
    kana: string;
    age: number;
    /** 免許証の色。 */
    licenseColor: string;
    /** 職業。 */
    occupation: string;
    /** 使用の本拠地（架空の地名）。 */
    baseArea: string;
    /** ノンフリート等級。 */
    grade: number;
    /** 事故有係数適用期間（年）。 */
    accidentCoefficientYears: number;
  };

  vehicle: {
    /** 架空のメーカー名。 */
    maker: string;
    /** 架空の車種名。 */
    model: string;
    /** 型式（架空）。 */
    modelCode: string;
    /** 初度登録年月。 */
    firstRegistered: string;
    /** 用途・車種区分。 */
    usage: string;
    /** 使用目的。 */
    purpose: string;
    /** 年間予定走行距離（km）。 */
    annualMileage: number;
    /** 車両保険金額（円）。 */
    vehicleInsuredAmount: number;
    /** 安全装置。 */
    safetyDevices: string;
  };

  coverages: Coverage[];
  riders: Rider[];
  discounts: Discount[];

  /** 基本保険料（車両保険料を含む、年額・円）。 */
  basePremium: number;
  /** 上のうち車両保険料（円）。免責金額を上げたときの減額はここから計算する。 */
  vehiclePremium: number;
  /** 現在の車両保険の免責金額（円・1回目）。 */
  currentDeductible: number;

  /** 決裁ルールの判定対象となる保険金額（対人・対物・車両の合計、円）。 */
  insuredAmountTotal: number;

  criteria: Criterion[];
  accidents: Accident[];
  activity: ActivityEntry[];

  /** 他社での契約歴の要約（基準7の根拠になる元データ）。 */
  priorInsurance: string;
}

/** 担当者が下せる判断。 */
export type DecisionKind = "accept" | "conditional" | "decline";

/** 確定した判断の控え。監査で読まれる想定なので、当時の値をすべて写し取る。 */
export interface Submission {
  caseId: string;
  decision: DecisionKind;
  reason: string;
  conditionLines: string[];
  declineReasonLabel: string | null;
  quotedPremium: number;
  finalPremium: number;
  /** 判断した時点の自動判定の内訳。 */
  criteriaSnapshot: {
    pass: number;
    review: number;
    fail: number;
    /** 合格でなかった項目の名前と判定。 */
    flagged: string[];
  };
  stage: ApprovalStage;
  routeReasons: string[];
  decidedBy: string;
  decidedAt: string;
}

/** 条件付き引受で担当者が動かせるつまみ。 */
export interface DecisionConditions {
  /** 車両保険の免責金額（円・1回目）。 */
  deductible: number;
  /** 外す特約の id。 */
  removedRiderIds: string[];
  /** 保険料の割増率（％）。 */
